# Problem 1
def fmt(t):
    return f"{t // 60:02d}:{t % 60:02d}"

participants = ["Jack", "Charlotte"]
days = ["Monday"]
work_start = 9 * 60
work_end = 17 * 60
duration = 30

busy = {
    "Monday": {
        "Jack": [
            (9 * 60 + 30, 10 * 60 + 30),
            (11 * 60, 11 * 60 + 30),
            (12 * 60 + 30, 13 * 60),
            (14 * 60, 14 * 60 + 30),
            (16 * 60, 16 * 60 + 30),
        ],
        "Charlotte": [
            (9 * 60 + 30, 10 * 60),
            (10 * 60 + 30, 12 * 60),
            (12 * 60 + 30, 13 * 60 + 30),
            (14 * 60, 16 * 60),
        ],
    }
}

def fits(day, start):
    end = start + duration
    if end > work_end:
        return False
    for person in participants:
        for s, e in busy[day].get(person, []):
            if start < e and end > s:
                return False
    return True

preferred = []
for day in days:
    for start in range(work_start, work_end - duration + 1, 30):
        if fits(day, start):
            if start <= 12 * 60 + 30:
                preferred.append((day, start, start + duration))

if not preferred:
    for day in days:
        for start in range(work_start, work_end - duration + 1, 30):
            if fits(day, start):
                preferred.append((day, start, start + duration))

day, start, end = preferred[0]
print([day, fmt(start), fmt(end)])

